        // 3. Audio (MP3 / OGG)
        text = text.replace(/(https?:\/\/\S+?\.(?:mp3|ogg))/gi, `<div class="media-container"><audio controls preload="metadata"><source src="$1"></audio></div>`);

        text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
        text = text.replace(/\*(.+?)\*/g, '<strong>$1</strong>');
        text = text.replace(/_(.+?)_/g, '<em>$1</em>');
